function smallestUniqueLetters(s: string): string {
  let out = "";
  while (s.length > 0) {
    const need = new Set(s);
    let pick = "";
    for (const c of [...need].sort()) {
      const tail = s.slice(s.indexOf(c));
      if ([...need].every(x => tail.includes(x))) { pick = c; break; }
    }
    out += pick;
    // keep what follows the chosen letter, without any more copies of it
    s = s.slice(s.indexOf(pick) + 1).split(pick).join("");
  }
  return out;
}

