class Solution:
    def smallestUniqueLetters(self, s: str) -> str:
        out = []
        while s:
            need = set(s)
            for c in sorted(need):
                if set(s[s.index(c):]) >= need:
                    break
            out.append(c)
            # keep what follows the chosen letter, without any more copies of it
            s = s[s.index(c) + 1:].replace(c, "")
        return "".join(out)

